import {clone,hash,seal,verifySeal,uniq,AAFError,isHex64} from './canonical.mjs';
const req=(c,code)=>{if(!c)throw new AAFError(code)};
export function sealPolicyBundle(raw){const out={format:'aaf.policy-bundle.v0.1',bundle_id:String(raw.bundle_id??''),version:String(raw.version??'0.1.0'),default_effect:String(raw.default_effect??'deny'),policies:clone(raw.policies??[]).sort((a,b)=>String(a.policy_id).localeCompare(String(b.policy_id),'en')),metadata:clone(raw.metadata??{})};req(out.bundle_id,'POLICY_BUNDLE_ID_REQUIRED');req(['allow','deny'].includes(out.default_effect),'POLICY_DEFAULT_EFFECT_INVALID');return seal(out,'policy_bundle_root');}
export function verifyPolicyBundle(v){if(v?.format!=='aaf.policy-bundle.v0.1')return false;const o=clone(v);delete o.signature;return verifySeal(o,'policy_bundle_root');}
export function sealDelegation(raw){const out={format:'aaf.delegation.v0.1',delegation_id:String(raw.delegation_id??''),issuer_id:String(raw.issuer_id??''),delegate_id:String(raw.delegate_id??''),scopes:uniq(raw.scopes),capability_patterns:uniq(raw.capability_patterns??['*']),constraints:clone(raw.constraints??{}),not_before:String(raw.not_before??''),expires_at:String(raw.expires_at??''),max_depth:Number(raw.max_depth??0),parent_delegation_id:raw.parent_delegation_id?String(raw.parent_delegation_id):null};req(out.delegation_id&&out.issuer_id&&out.delegate_id,'DELEGATION_IDENTITY_REQUIRED');req(Number.isSafeInteger(out.max_depth)&&out.max_depth>=0,'DELEGATION_DEPTH_INVALID');return seal(out,'delegation_root');}
export function verifyDelegation(v){if(v?.format!=='aaf.delegation.v0.1')return false;const o=clone(v);delete o.signature;return verifySeal(o,'delegation_root');}
export function sealApproval(raw){const out={format:'aaf.approval-receipt.v0.1',approval_id:String(raw.approval_id??''),proposal_root:String(raw.proposal_root??''),approver_id:String(raw.approver_id??''),approver_roles:uniq(raw.approver_roles),decision:String(raw.decision??'approved'),scopes:uniq(raw.scopes??['*']),conditions:clone(raw.conditions??[]),issued_at:String(raw.issued_at??''),expires_at:String(raw.expires_at??'')};req(out.approval_id&&out.approver_id,'APPROVAL_IDENTITY_REQUIRED');req(isHex64(out.proposal_root),'APPROVAL_PROPOSAL_ROOT_INVALID');req(['approved','denied'].includes(out.decision),'APPROVAL_DECISION_INVALID');return seal(out,'approval_root');}
export function verifyApproval(v){if(v?.format!=='aaf.approval-receipt.v0.1')return false;const o=clone(v);delete o.signature;return verifySeal(o,'approval_root');}
export function sealRevocationRegistry(raw){const out={format:'aaf.revocation-registry.v0.1',registry_id:String(raw.registry_id??''),revoked_delegations:uniq(raw.revoked_delegations),revoked_approvals:uniq(raw.revoked_approvals),updated_at:String(raw.updated_at??'')};req(out.registry_id,'REVOCATION_REGISTRY_ID_REQUIRED');return seal(out,'revocation_root');}
export function verifyRevocationRegistry(v){if(v?.format!=='aaf.revocation-registry.v0.1')return false;const o=clone(v);delete o.signature;return verifySeal(o,'revocation_root');}
export function makeAuthorityRequest(raw){const out={format:'aaf.authority-request.v0.1',request_id:String(raw.request_id??''),proposal_root:String(raw.proposal_root??raw.envelope?.proposal_root??''),envelope_root:String(raw.envelope_root??raw.envelope?.envelope_root??''),subject:clone(raw.subject??raw.envelope?.subject??{}),requested_scopes:uniq(raw.requested_scopes??raw.envelope?.capability_plan?.required_scopes),capability_steps:clone(raw.capability_steps??[]),context:clone(raw.context??{}),policy_bundle_root:String(raw.policy_bundle_root??''),delegation_roots:uniq(raw.delegation_roots),approval_roots:uniq(raw.approval_roots)};req(out.request_id,'AUTHORITY_REQUEST_ID_REQUIRED');req(isHex64(out.proposal_root),'AUTHORITY_PROPOSAL_ROOT_INVALID');req(out.subject?.subject_id,'AUTHORITY_SUBJECT_REQUIRED');return seal(out,'authority_request_root');}
export function verifyAuthorityRequest(v){return v?.format==='aaf.authority-request.v0.1'&&verifySeal(v,'authority_request_root');}
